const staticData = $getWorkflowStaticData('global');
const values = items[0].json.values || [];
if (!Array.isArray(values) || values.length < 2) return [];
const headers = (values[0] || []).map((h) => String(h || '').trim());
const seen = staticData.seenFormTs2 || {};
const out = [];
for (let i = 1; i < values.length; i++) {
  const row = values[i] || [];
  const obj = {};
  headers.forEach((h, idx) => { obj[h] = String(row[idx] || '').trim(); });
  const ts = obj.Timestamp || ('row-' + i);
  if (seen[ts]) continue;
  seen[ts] = 1;
  out.push({ json: obj });
}
staticData.seenFormTs2 = seen;
return out;

const raw = items[0].json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const nv = body.namedValues && typeof body.namedValues === 'object' ? body.namedValues : {};

function pick(obj, keys) {
  const bag = {};
  for (const [key, value] of Object.entries(obj || {})) {
    bag[String(key).trim().toLowerCase()] = value;
  }
  for (const key of keys) {
    const value = bag[String(key).trim().toLowerCase()];
    if (Array.isArray(value) && value[0]) return String(value[0]).trim();
    if (value != null && String(value).trim()) return String(value).trim();
  }
  return '';
}

function pickPassport(obj) {
  const exact = pick(obj, ['passportNo', 'Passport', 'Passport no', 'Passport No', 'Passport number', 'Passport Number']);
  if (exact) return exact;
  for (const [key, value] of Object.entries(obj || {})) {
    if (/passport|နိုင်ငံကူးလက်မှတ်/i.test(String(key))) {
      const hit = Array.isArray(value) ? value[0] : value;
      if (hit != null && String(hit).trim()) return String(hit).trim();
    }
  }
  return '';
}

const keysName = ['fullName', 'Name', 'Full name', 'Full Name (Passport)'];
const keysEmail = ['email', 'Email', 'E-mail', 'Email Address', 'emailAddress', 'E-mail Address'];
const keysPhone = ['phone', 'Phone', 'Phone or viber Number', 'Phone Number or Viber', 'mobile', 'tel'];
const keysNat = ['country', 'Country', 'nationality', 'Nationality'];
const keysMessage = ['message', 'Message', 'Symptoms or Health Concerns', 'Resident Address', 'address', 'Address'];

const fullName = pick(body, keysName) || pick(nv, keysName);
const email = pick(body, keysEmail) || pick(nv, keysEmail);
const phone = pick(body, keysPhone) || pick(nv, keysPhone);
const country = pick(body, keysNat) || pick(nv, keysNat) || 'Myanmar';
const message = pick(body, keysMessage) || pick(nv, keysMessage) || 'Visit request (Google Form)';
const passportNo = pickPassport(body) || pickPassport(nv);

return [{ json: { source: 'google_form', fullName, email, phone, country, locale: 'en', message, returningPatient: false, consent: true, passportNo } }];
